import { useState } from 'react';

export default function UrlScanner() {
  const [url, setUrl] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  async function scanUrl() {
    setLoading(true);
    try {
      const res = await fetch('/api/tools/url-scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url }),
      });
      const data = await res.json();
      setResult(data);
    } catch (err) {
      setResult({ verdict: 'Error', signals: [err.message] });
    } finally {
      setLoading(false);
    }
  }

  return (
    <div>
      <h2>URL Scanner</h2>
      <input
        type="text"
        value={url}
        onChange={(e) => setUrl(e.target.value)}
        placeholder="https://example.com"
      />
      <button onClick={scanUrl} disabled={loading || !url}>
        {loading ? 'Scanning...' : 'Scan'}
      </button>

      {result && (
        <div>
          <h3>Verdict: {result.verdict}</h3>
          <ul>
            {result.signals?.map((s, i) => <li key={i}>{s}</li>)}
          </ul>
          {result.cert && (
            <p>SSL Cert valid until: {result.cert.validTo}</p>
          )}
        </div>
      )}
    </div>
  );
}
